function resetGame(fullReset = false) {
    // Clear active entities
    clearActiveEntities();

    if (fullReset) {
        // Full game reset
        scoringSystem.reset();

        // Recreate player with full health
        if (player) {
            player.dispose();
        }
        player = new Player(scene, cameraShake, particleManager, motionTrails);

        // Reset invader grid to level 1 formation
        invaderGrid.resetToLevel(1);
    } else {
        // Continue to next level
        const nextLevel = scoringSystem.getCurrentLevel() + 1;
        invaderGrid.resetToLevel(nextLevel);
        player.respawn();
    }

    // Reset UFO timer
    ufo.resetTimer();
}

function clearActiveEntities() {
    // Return all bullets to pool
    activeBullets.forEach(bullet => bulletPool.release(bullet));
    activeBullets = [];

    // Return all bombs to pool
    activeBombs.forEach(bomb => bombPool.release(bomb));
    activeBombs = [];

    // Return all power-ups to pool
    activePowerUps.forEach(powerUp => powerUpPool.release(powerUp));
    activePowerUps = [];
}

function resumeGame() {
    // Game resumed from pause - nothing special needed
    // TimeManager will automatically resume delta time
}

// ============================================
// Main Game Loop
// ============================================

function gameLoop(timestamp) {
    animationFrameId = requestAnimationFrame(gameLoop);

    // Get delta time (handles pause/slow-mo via TimeManager)
    const delta = TimeManager.getDelta();

    // Check for hit-stop (frozen time)
    if (!hitStopManager.update(delta)) {
        return; // Skip this frame if frozen
    }

    // Update game state machine first
    gameStateMachine.update(delta);

    // Only update gameplay if in PLAYING state
    if (gameStateMachine.getCurrentState() !== 'PLAYING') {
        renderer.render(scene, camera);
        return;
    }

    // Initialize audio context on first user interaction
    AudioContextManager.ensureInitialized();

    // Update input
    const input = inputHandler.update(delta);

    // Update player
    if (player && !player.isDead) {
        player.update(delta, input);

        // Handle shooting
        if (input.actions.shoot) {
            const bullet = player.tryShoot(bulletPool.acquire);
            if (bullet) {
                activeBullets.push(bullet);

                // Add motion trail for bullet
                motionTrails.addTrail(bullet.mesh, 0x00ffff, 15);
            }
        }
    }

    // Update invader grid
    invaderGrid.update(delta);

    // Check if invaders reached player level (game over)
    if (invaderGrid.hasReachedBottom()) {
        gameStateMachine.setGameOver();
    }

    // Update UFO
    ufo.update(delta, () => spawnUFO());

    // Update active bullets
    updateBullets(delta);

    // Update active bombs
    updateBombs(delta);

    // Update power-ups
    updatePowerUps(delta);

    // Perform collision detection
    performCollisions();

    // Update VFX systems
    particleManager.update(delta);
    shockwaveRings.update(delta);
    floatingTextPool.update(delta);
    motionTrails.update(delta);

    // Update starfield parallax
    updateStarfield(delta);

    // Render with post-processing
    composer.render();
}

function spawnUFO() {
    const ufoInstance = ufo.spawn();
    if (ufoInstance) {
        // UFO is now active, will be handled in its own update cycle
    }
}

function updateBullets(delta) {
    for (let i = activeBullets.length - 1; i >= 0; i--) {
        const bullet = activeBullets[i];
        bullet.update(delta);

        // Remove if out of bounds
        if (bullet.isOutOfBounds()) {
            bulletPool.release(bullet);
            motionTrails.removeTrail(bullet.mesh);
            activeBullets.splice(i, 1);
        }
    }
}

function updateBombs(delta) {
    for (let i = activeBombs.length - 1; i >= 0; i--) {
        const bomb = activeBombs[i];
        bomb.update(delta);

        // Remove if out of bounds
        if (bomb.isOutOfBounds()) {
            bombPool.release(bomb);
            activeBombs.splice(i, 1);
        }
    }
}

function updatePowerUps(delta) {
    for (let i = activePowerUps.length - 1; i >= 0; i--) {
        const powerUp = activePowerUps[i];
        powerUp.update(delta);

        // Remove if out of bounds or collected
        if (powerUp.isRemoved()) {
            powerUpPool.release(powerUp);
            activePowerUps.splice(i, 1);
        }
    }
}

function performCollisions() {
    // Bullet vs Invaders
    for (let i = activeBullets.length - 1; i >= 0; i--) {
        const bullet = activeBullets[i];

        // Check against each invader in the grid
        const hitInvader = invaderGrid.checkCollision(bullet);

        if (hitInvader) {
            // Destroy bullet
            bulletPool.release(bullet);
            motionTrails.removeTrail(bullet.mesh);
            activeBullets.splice(i, 1);

            // Handle invader death
            handleInvaderDeath(hitInvader);

            continue;
        }
    }

    // Bomb vs Player
    for (let i = activeBombs.length - 1; i >= 0; i--) {
        const bomb = activeBombs[i];

        if (player && !player.isDead && collisionSystem.checkAABB(bomb.mesh, player.mesh)) {
            // Destroy bomb
            bombPool.release(bomb);
            activeBombs.splice(i, 1);

            // Handle player hit
            handlePlayerHit(bomb.position.clone());
        }
    }

    // Power-up vs Player
    for (let i = activePowerUps.length - 1; i >= 0; i--) {
        const powerUp = activePowerUps[i];

        if (player && !player.isDead && collisionSystem.checkAABB(powerUp.mesh, player.mesh)) {
            // Collect power-up
            handlePowerUpCollected(powerUp);

            // Remove from scene
            powerUpPool.release(powerUp);
            activePowerUps.splice(i, 1);
        }
    }

    // UFO vs Bullets
    if (ufo.isActive()) {
        for (let i = activeBullets.length - 1; i >= 0; i--) {
            const bullet = activeBullets[i];

            if (collisionSystem.checkAABB(bullet.mesh, ufo.getMesh())) {
                // Destroy bullet
                bulletPool.release(bullet);
                motionTrails.removeTrail(bullet.mesh);
                activeBullets.splice(i, 1);

                // Handle UFO death
                handleUFODestruction(ufo.getPosition());

                break;
            }
        }
    }
}

function handleInvaderDeath(invader) {
    const position = invader.position.clone();
    const type = invader.type;

    // Spawn explosion particles
    particleManager.spawnExplosion(position, type === 'squid' ? 50 : 30);

    // Spawn shockwave ring
    shockwaveRings.spawn(position, 4, 0x00ffff);

    // Add floating text for points
    const points = scoringSystem.getPointsForType(type);
    floatingTextPool.spawn(`+${points}`, position, 0xffff00);

    // Play death sound
    sfxSynth.playInvaderDeath();

    // Score the kill
    scoringSystem.addScore(points);

    // Check for power-up drop (10% chance)
    if (Math.random() < 0.1) {
        spawnPowerUp(position);
    }

    // Remove invader from grid
    invaderGrid.removeInvader(invader);

    // Add camera shake based on invader type
    const shakeIntensity = type === 'squid' ? 2 : 1;
    cameraShake.addTrauma(shakeIntensity);
}

function handlePlayerHit(hitPosition) {
    // Spawn explosion particles
    particleManager.spawnExplosion(hitPosition, 40);

    // Add hit-stop for dramatic effect
    hitStopManager.trigger(8);

    // Play hit sound
    sfxSynth.playPlayerHit();

    // Add strong camera shake
    cameraShake.addTrauma(3);

    // Lose a life
    const lives = scoringSystem.decrementLife();

    if (lives <= 0) {
        // Player died - game over
        player.die(particleManager, shockwaveRings);
        gameStateMachine.setGameOver();
    } else {
        // Respawn after brief delay
        player.respawn();

        // Clear nearby bombs for fairness
        activeBombs.forEach(bomb => bombPool.release(bomb));
        activeBombs = [];
    }
}

function handlePowerUpCollected(powerUp) {
    const type = powerUp.getType();

    // Apply power-up effect to player
    player.activatePowerUp(type);

    // Play collection sound
    sfxSynth.playPowerUpCollect();

    // Show floating text
    const textMap = {
        'spread': 'SPREAD!',
        'rapid': 'RAPID!',
        'shield': 'SHIELD!'
    };
    floatingTextPool.spawn(textMap[type] || '+', powerUp.position.clone(), 0x00ff00);
}

function handleUFODestruction(position) {
    // Massive explosion
    particleManager.spawnExplosion(position, 60);

    // Large shockwave
    shockwaveRings.spawn(position, 8, 0xff00ff);

    // Hit-stop for dramatic effect
    hitStopManager.trigger(10);

    // Play UFO death sound
    sfxSynth.playUFODestruction();

    // Score based on direction (UFO tracks this internally)
    const points = ufo.getScoreValue();
    scoringSystem.addScore(points);
    floatingTextPool.spawn(`+${points}`, position, 0xff00ff, 32);

    // Reset UFO timer
    ufo.resetTimer();
}

function spawnPowerUp(position) {
    const powerTypes = ['spread', 'rapid', 'shield'];
    const type = powerTypes[Math.floor(Math.random() * powerTypes.length)];

    const powerUp = powerUpPool.acquire(type);
    powerUp.init(position.clone());
    activePowerUps.push(powerUp);
}

function updateStarfield(delta) {
    starfieldLayers.forEach(layer => layer.update(delta));
}

// ============================================
// Pause/Resume Functions
// ============================================

function togglePause() {
    if (gameStateMachine.getCurrentState() === 'PLAYING') {
        gameStateMachine.setPaused();
    } else if (gameStateMachine.getCurrentState() === 'PAUSED') {
        gameStateMachine.setPlaying();
    }
}

// ============================================
// Window Resize Handler
// ============================================

function handleResize() {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();

    renderer.setSize(window.innerWidth, window.innerHeight);
    composer.setSize(window.innerWidth, window.innerHeight);
}

window.addEventListener('resize', handleResize);

// ============================================
// Keyboard Event Handlers
// ============================================

function handleKeyDown(event) {
    // Pause toggle with Escape or P
    if (event.key === 'Escape' || event.key.toLowerCase() === 'p') {
        togglePause();
    }

    // Start game on any key when at start screen
    if (gameStateMachine.getCurrentState() === 'MENU') {
        gameStateMachine.setPlaying();
    } else if (gameStateMachine.getCurrentState() === 'GAME_OVER') {
        resetGame(true);
        gameStateMachine.setPlaying();
    }
}

function handleKeyUp(event) {
    // Handled by InputHandler internally
}

window.addEventListener('keydown', handleKeyDown);
window.addEventListener('keyup', handleKeyUp);

// ============================================
// Game Start Entry Point
// ============================================

async function startGame() {
    try {
        // Initialize all systems
        initThreeJS();
        initLighting();

        const vfxSystems = initVFXSystems();
        const { cameraShake } = vfxSystems;

        initAudio();
        initEntityPools();
        initStarfield();
        initGameEntities();
        initMechanics();
        initUI();

        // Start the game loop
        animationFrameId = requestAnimationFrame(gameLoop);

        console.log('Space Invaders AAA Reimagining - Ready to play!');
        console.log('Controls: WASD/Arrows to move, SPACE to shoot');
        console.log('Press P or ESC to pause');

    } catch (error) {
        console.error('Failed to initialize game:', error);
    }
}

// Start the game when DOM is ready
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', startGame);
} else {
    startGame();
}

// Export for module systems
export { startGame, resetGame };

import * as THREE from 'three';
import { GeometryPool } from '../../shared/rendering/GeometryPool.js';
import { PBRMaterialFactory } from '../../shared/rendering/PBRMaterialFactory.js';

export class Bullet {
    constructor() {
        this.active = false;
        this.position = new THREE.Vector3();
        this.velocity = new THREE.Vector3(0, 1, 0);
        this.speed = 80;

        // Create bullet mesh
        const geometry = GeometryPool.get('bullet');
        const material = PBRMaterialFactory.createBulletMaterial();

        this.mesh = new THREE.Mesh(geometry, material);
        this.mesh.visible = false;

        // Bounding box for collision
        this.aabb = {
            minX: -0.15, maxX: 0.15,
            minY: -0.3, maxY: 0.3,
            minZ: -0.15, maxZ: 0.15
        };
    }

    activate(x, z) {
        this.active = true;
        this.position.set(x, -6, z);
        this.mesh.position.copy(this.position);
        this.mesh.visible = true;
        this.velocity.set(0, this.speed, 0);
    }

    deactivate() {
        this.active = false;
        this.mesh.visible = false;
        this.mesh.position.set(0, -100, 0); // Move off-screen
    }

    update(delta) {
        if (!this.active) return;

        // Move bullet upward
        this.position.y += this.velocity.y * delta;
        this.mesh.position.copy(this.position);

        // Deactivate if out of bounds
        if (this.position.y > 12) {
            this.deactivate();
        }
    }

    getBounds() {
        return {
            minX: this.position.x + this.aabb.minX,
            maxX: this.position.x + this.aabb.maxX,
            minY: this.position.y + this.aabb.minY,
            maxY: this.position.y + this.aabb.maxY,
            minZ: this.position.z + this.aabb.minZ,
            maxZ: this.position.z + this.aabb.maxZ
        };
    }

    dispose() {
        // Geometry is pooled, material is shared - no disposal needed
        this.deactivate();
    }
}

/**
 * PBR Material Factory
 * Creates and manages MeshStandardMaterial presets for AAA Retro-Futurism aesthetic
 */

import * as THREE from 'three';

class PBRMaterialFactory {
    constructor() {
        this.materialCache = new Map();
        this.defaultMetalness = 0.4;
        this.defaultRoughness = 0.3;
    }

    /**
     * Create a neon emissive material for glowing objects
     */
    createNeonMaterial(color, emissiveIntensity = 1.5) {
        const key = `neon_${color}_${emissiveIntensity}`;
        if (this.materialCache.has(key)) {
            return this.materialCache.get(key).clone();
        }

        const material = new THREE.MeshStandardMaterial({
            color: 0x111111,
            emissive: new THREE.Color(color),
            emissiveIntensity: emissiveIntensity,
            metalness: this.defaultMetalness,
            roughness: this.defaultRoughness,
            envMapIntensity: 1.0
        });

        this.materialCache.set(key, material);
        return material.clone();
    }

    /**
     * Create a metallic sci-fi material for ships and structures
     */
    createMetallicMaterial(baseColor, metalness = 0.7, roughness = 0.2) {
        const key = `metal_${baseColor}_${metalness}_${roughness}`;
        if (this.materialCache.has(key)) {
            return this.materialCache.get(key).clone();
        }

        const material = new THREE.MeshStandardMaterial({
            color: baseColor,
            metalness: metalness,
            roughness: roughness,
            envMapIntensity: 1.2
        });

        this.materialCache.set(key, material);
        return material.clone();
    }

    /**
     * Create a transparent glass/plasma material for shields and energy effects
     */
    createGlassMaterial(color, opacity = 0.3, transmission = 0.5) {
        const key = `glass_${color}_${opacity}_${transmission}`;
        if (this.materialCache.has(key)) {
            return this.materialCache.get(key).clone();
        }

        const material = new THREE.MeshStandardMaterial({
            color: color,
            transparent: true,
            opacity: opacity,
            metalness: 0.1,
            roughness: 0.05,
            transmission: transmission,
            thickness: 1.0,
            envMapIntensity: 1.5
        });

        this.materialCache.set(key, material);
        return material.clone();
    }

    /**
     * Create a particle material for VFX
     */
    createParticleMaterial(color, additiveBlending = true) {
        const key = `particle_${color}_${additiveBlending}`;
        if (this.materialCache.has(key)) {
            return this.materialCache.get(key).clone();
        }

        const material = new THREE.MeshStandardMaterial({
            color: color,
            emissive: color,
            emissiveIntensity: 2.0,
            transparent: true,
            opacity: 1.0,
            depthWrite: false,
            blending: additiveBlending ? THREE.AdditiveBlending : THREE.NormalBlending,
            side: THREE.DoubleSide
        });

        this.materialCache.set(key, material);
        return material.clone();
    }

    /**
     * Create a shockwave ring material with strong emissive glow
     */
    createShockwaveMaterial(color = 0x00ffff) {
        const key = `shockwave_${color}`;
        if (this.materialCache.has(key)) {
            return this.materialCache.get(key).clone();
        }

        const material = new THREE.MeshStandardMaterial({
            color: 0xffffff,
            emissive: color,
            emissiveIntensity: 3.0,
            transparent: true,
            opacity: 1.0,
            side: THREE.DoubleSide,
            depthWrite: false
        });

        this.materialCache.set(key, material);
        return material.clone();
    }

    /**
     * Create a trail ribbon material for motion trails
     */
    createTrailMaterial(color) {
        const key = `trail_${color}`;
        if (this.materialCache.has(key)) {
            return this.materialCache.get(key).clone();
        }

        const material = new THREE.MeshStandardMaterial({
            color: color,
            emissive: color,
            emissiveIntensity: 1.0,
            transparent: true,
            opacity: 0.8,
            depthWrite: false,
            side: THREE.DoubleSide
        });

        this.materialCache.set(key, material);
        return material.clone();
    }

    /**
     * Create a sprite material for floating text and UI elements
     */
    createSpriteMaterial(texture) {
        const material = new THREE.SpriteMaterial({
            map: texture,
            transparent: true,
            depthWrite: false,
            blending: THREE.NormalBlending
        });
        return material;
    }

    /**
     * Create a starfield point material
     */
    createStarMaterial(color = 0xffffff) {
        const key = `star_${color}`;
        if (this.materialCache.has(key)) {
            return this.materialCache.get(key).clone();
        }

        const material = new THREE.PointsMaterial({
            color: color,
            size: 0.1,
            transparent: true,
            opacity: 0.8,
            depthWrite: false
        });

        this.materialCache.set(key, material);
        return material.clone();
    }

    /**
     * Create a power-up collectible material with pulsing effect capability
     */
    createPowerUpMaterial(baseColor) {
        const key = `powerup_${baseColor}`;
        if (this.materialCache.has(key)) {
            return this.materialCache.get(key).clone();
        }

        const material = new THREE.MeshStandardMaterial({
            color: baseColor,
            emissive: baseColor,
            emissiveIntensity: 2.0,
            metalness: 0.5,
            roughness: 0.1,
            envMapIntensity: 1.5
        });

        this.materialCache.set(key, material);
        return material.clone();
    }

    /**
     * Create a UFO special material with unique properties
     */
    createUFOMaterial() {
        const key = `ufo`;
        if (this.materialCache.has(key)) {
            return this.materialCache.get(key).clone();
        }

        const material = new THREE.MeshStandardMaterial({
            color: 0xff3366,
            emissive: 0xff0044,
            emissiveIntensity: 1.8,
            metalness: 0.8,
            roughness: 0.15,
            envMapIntensity: 1.3
        });

        this.materialCache.set(key, material);
        return material.clone();
    }

    /**
     * Dispose all cached materials (call on game shutdown)
     */
    disposeAll() {
        for (const [, material] of this.materialCache) {
            material.dispose();
        }
        this.materialCache.clear();
    }
}

