import * as THREE from 'three';
import { GeometryPool } from '../../shared/rendering/GeometryPool.js';
import { PBRMaterialFactory } from '../../shared/rendering/PBRMaterialFactory.js';

export class Bomb {
    constructor() {
        this.geometry = GeometryPool.get('sphere');
        this.material = new THREE.MeshStandardMaterial({
            color: 0xff3300,
            emissive: 0xff6600,
            emissiveIntensity: 1.5,
            metalness: 0.7,
            roughness: 0.3
        });

        this.mesh = new THREE.Mesh(this.geometry, this.material);
        this.mesh.visible = false;

        this.velocity = new THREE.Vector3(0, -40, 0);
        this.active = false;
        this.position = new THREE.Vector3();
    }

    activate(x, y) {
        this.active = true;
        this.mesh.position.set(x, y, 0);
        this.mesh.visible = true;
        this.velocity.y = -40; // Downward velocity
    }

    deactivate() {
        this.active = false;
        this.mesh.visible = false;
    }

    update(delta) {
        if (!this.active) return;

        this.mesh.position.addScaledVector(this.velocity, delta);

        // Deactivate if below player area
        if (this.mesh.position.y < -10) {
            this.deactivate();
        }
    }

    dispose() {
        this.material.dispose();
        this.mesh.geometry = null;
        this.mesh.material = null;
    }
}

import * as THREE from 'three';
import { PBRMaterialFactory } from '../../shared/rendering/PBRMaterialFactory.js';
import { GeometryPool } from '../../shared/rendering/GeometryPool.js';
import { AABB } from '../../shared/utils/AABB.js';

export class Player {
    constructor(scene, position = new THREE.Vector3(0, -8, 0)) {
        this.scene = scene;
        this.position = position.clone();
        this.velocity = new THREE.Vector3(0, 0, 0);

        // Movement properties
        this.speed = 12;
        this.moveDirection = 0; // -1 left, 0 none, 1 right

        // Shooting properties
        this.fireCooldown = 0;
        this.fireRate = 0.4; // seconds between shots

        // Power-ups
        this.hasSpreadShot = false;
        this.hasRapidFire = false;
        this.spreadShotTimer = 0;
        this.rapidFireTimer = 0;

        // Shield
        this.shieldActive = false;
        this.shieldHealth = 1;

        // AABB for collision
        this.aabb = new AABB(
            position.x - 0.8, position.y - 0.6, position.z - 0.3,
            position.x + 0.8, position.y + 0.6, position.z + 0.3
        );

        // Create mesh
        this.createMesh();
    }

    createMesh() {
        const geometry = GeometryPool.get('playerShip');
        const material = PBRMaterialFactory.createNeonGlowMaterial(0x00ffff, 2);

        this.mesh = new THREE.Mesh(geometry, material);
        this.mesh.position.copy(this.position);
        this.mesh.castShadow = true;

        // Add glow point light
        this.glowLight = new THREE.PointLight(0x00ffff, 1.5, 12);
        this.glowLight.position.set(0, -1, 0);
        this.mesh.add(this.glowLight);

        // Shield mesh (hidden by default)
        const shieldGeometry = GeometryPool.get('shield');
        const shieldMaterial = PBRMaterialFactory.createEnergyShieldMaterial();
        this.shieldMesh = new THREE.Mesh(shieldGeometry, shieldMaterial);
        this.shieldMesh.position.copy(this.position);
        this.shieldMesh.visible = false;

        this.scene.add(this.mesh);
        this.scene.add(this.shieldMesh);
    }

    update(delta) {
        // Apply movement
        if (this.moveDirection !== 0) {
            const moveAmount = this.speed * delta * this.moveDirection;
            this.position.x += moveAmount;

            // Clamp to viewport bounds
            this.position.x = Math.max(-12, Math.min(12, this.position.x));
        }

        // Update mesh position
        this.mesh.position.copy(this.position);
        this.shieldMesh.position.copy(this.position);

        // Update AABB
        this.aabb.setFromCenterAndSize(
            this.position,
            new THREE.Vector3(1.6, 1.2, 0.6)
        );

        // Update fire cooldown
        if (this.fireCooldown > 0) {
            this.fireCooldown -= delta;
        }

        // Update power-up timers
        if (this.hasSpreadShot) {
            this.spreadShotTimer -= delta;
            if (this.spreadShotTimer <= 0) {
                this.hasSpreadShot = false;
            }
        }

        if (this.hasRapidFire) {
            this.rapidFireTimer -= delta;
            if (this.rapidFireTimer <= 0) {
                this.hasRapidFire = false;
            }
        }

        // Update shield visibility and rotation
        this.shieldMesh.visible = this.shieldActive && this.shieldHealth > 0;
        if (this.shieldMesh.visible) {
            this.shieldMesh.rotation.y += 3 * delta;
        }
    }

    setMoveDirection(direction) {
        this.moveDirection = direction;
    }

    canFire() {
        return this.fireCooldown <= 0;
    }

    fire(bulletPool, motionTrailsManager) {
        if (!this.canFire()) return [];

        const bullets = [];
        const currentFireRate = this.hasRapidFire ? 0.2 : this.fireRate;
        this.fireCooldown = currentFireRate;

        // Determine angles for spread shot
        const angles = this.hasSpreadShot 
            ? [-0.26, 0, 0.26] // -15°, 0°, +15° in radians
            : [0];

        for (const angle of angles) {
            const bullet = bulletPool.acquire();
            bullet.init(
                this.position.clone(),
                new THREE.Vector3(Math.sin(angle), Math.cos(angle), 0).multiplyScalar(80)
            );

            if (motionTrailsManager) {
                motionTrailsManager.addTrail(bullet.mesh, 0x00ffff);
            }

            bullets.push(bullet);
        }

        return bullets;
    }

    activateSpreadShot(duration = 10) {
        this.hasSpreadShot = true;
        this.spreadShotTimer = duration;
    }

    activateRapidFire(duration = 10) {
        this.hasRapidFire = true;
        this.rapidFireTimer = duration;
    }

    activateShield() {
        this.shieldActive = true;
        this.shieldHealth = 1;
    }

    takeBombHit() {
        if (this.shieldActive && this.shieldHealth > 0) {
            this.shieldHealth--;
            this.shieldMesh.material.opacity = this.shieldHealth / 2;

            if (this.shieldHealth <= 0) {
                this.shieldActive = false;
                this.shieldMesh.visible = false;
            }
            return true; // Blocked by shield
        }
        return false; // Direct hit
    }

    dispose() {
        // Remove from scene
        if (this.mesh.parent) {
            this.scene.remove(this.mesh);
        }

        if (this.shieldMesh.parent) {
            this.scene.remove(this.shieldMesh);
        }

        // Dispose materials and geometries
        this.mesh.geometry.dispose();
        this.mesh.material.dispose();
        this.glowLight.dispose();

        this.shieldMesh.geometry.dispose();
        this.shieldMesh.material.dispose();
    }
}

import * as THREE from 'three';
import { PBRMaterialFactory } from '../../shared/rendering/PBRMaterialFactory.js';
import { AABB } from '../../shared/utils/AABB.js';

export class UFO {
    constructor(scene, x, direction = 1) {
        this.scene = scene;
        this.direction = direction; // 1 = right to left, -1 = left to right

        // UFO geometry - saucer shape
        const topGeometry = new THREE.CylinderGeometry(0.8, 1.2, 0.3, 16);
        const bottomGeometry = new THREE.CylinderGeometry(1.2, 0.8, 0.2, 16);

        // Emissive material with green glow
        this.material = PBRMaterialFactory.createEmissive({
            color: 0x00ff88,
            emissive: 0x00ff44,
            emissiveIntensity: 3,
            metalness: 0.7,
            roughness: 0.2
        });

        this.topMesh = new THREE.Mesh(topGeometry, this.material);
        this.bottomMesh = new THREE.Mesh(bottomGeometry, this.material.clone());
        this.bottomMesh.position.y = -0.25;

        // Add dome on top
        const domeGeometry = new THREE.SphereGeometry(0.6, 16, 8, 0, Math.PI * 2, 0, Math.PI / 2);
        this.domeMesh = new THREE.Mesh(domeGeometry, PBRMaterialFactory.createEmissive({
            color: 0x88ffaa,
            emissive: 0x44ff66,
            emissiveIntensity: 2,
            metalness: 0.5,
            roughness: 0.1
        }));
        this.domeMesh.position.y = 0.3;

        // Group all meshes
        this.mesh = new THREE.Group();
        this.mesh.add(this.topMesh);
        this.mesh.add(this.bottomMesh);
        this.mesh.add(this.domeMesh);

        // Position at top of screen
        this.mesh.position.set(x, 6, 0);
        scene.add(this.mesh);

        // Movement properties
        this.speed = 4;
        this.alive = true;

        // AABB for collision
        this.aabb = new AABB(
            x - 1.5, y - 0.5, z - 0.2,
            x + 1.5, y + 0.5, z + 0.2
        );

        // Point value based on direction (alternating)
        this.points = direction === 1 ? 100 : (Math.random() > 0.5 ? 200 : 300);
    }

    update(delta, playerY) {
        if (!this.alive) return;

        // Move horizontally
        this.mesh.position.x += this.direction * this.speed * delta;

        // Update AABB
        const pos = this.mesh.position;
        this.aabb.min.set(pos.x - 1.5, pos.y - 0.5, pos.z - 0.2);
        this.aabb.max.set(pos.x + 1.5, pos.y + 0.5, pos.z + 0.2);

        // Check if off screen
        if ((this.direction === 1 && this.mesh.position.x < -18) ||
            (this.direction === -1 && this.mesh.position.x > 18)) {
            this.alive = false;
            return null; // Should be removed
        }

        return this;
    }

    destroy() {
        this.alive = false;
        this.scene.remove(this.mesh);

        // Dispose geometries and materials
        this.topMesh.geometry.dispose();
        this.bottomMesh.geometry.dispose();
        this.domeMesh.geometry.dispose();
        this.material.dispose();
        this.bottomMesh.material.dispose();
        this.domeMesh.material.dispose();
    }

    getBounds() {
        return this.aabb;
    }
}

import * as THREE from 'three';
import { GeometryPool } from '../../shared/rendering/GeometryPool.js';
import { PBRMaterialFactory } from '../../shared/rendering/PBRMaterialFactory.js';

export class PowerUp {
    constructor(x, y, type) {
        this.type = type; // 'spread', 'shield', 'rapid', 'health'
        this.active = true;
        this.position = new THREE.Vector3(x, y, 0);
        this.velocity = new THREE.Vector3(0, -2, 0);

        const size = 1.5;
        this.mesh = new THREE.Group();
        this.mesh.position.copy(this.position);

        // Create power-up orb with type-specific color and symbol
        const colors = {
            spread: 0xff4444,    // Red for spread shot
            shield: 0x44ff44,    // Green for shield
            rapid: 0xffff44,     // Yellow for rapid fire
            health: 0x4444ff     // Blue for health
        };

        const color = colors[this.type] || 0xffffff;

        // Outer glowing ring
        const ringGeo = GeometryPool.getTorus(0.6, 0.15, 8, 24);
        const ringMat = PBRMaterialFactory.createEmissive(color, 3);
        this.ringMesh = new THREE.Mesh(ringGeo, ringMat);
        this.mesh.add(this.ringMesh);

        // Inner core sphere
        const coreGeo = GeometryPool.getSphere(0.4, 16, 16);
        const coreMat = PBRMaterialFactory.createEmissive(color, 2);
        this.coreMesh = new THREE.Mesh(coreGeo, coreMat);
        this.mesh.add(this.coreMesh);

        // Pulsing effect variables
        this.pulsePhase = Math.random() * Math.PI * 2;
    }

    update(delta) {
        if (!this.active) return;

        // Move downward
        this.position.y += this.velocity.y * delta;
        this.mesh.position.copy(this.position);

        // Rotate for visual effect
        const rotationSpeed = 3 * delta;
        this.ringMesh.rotation.x += rotationSpeed;
        this.ringMesh.rotation.y += rotationSpeed * 0.7;
        this.coreMesh.rotation.x -= rotationSpeed;
        this.coreMesh.rotation.z += rotationSpeed * 0.5;

        // Pulse effect
        this.pulsePhase += 8 * delta;
        const pulseScale = 1 + Math.sin(this.pulsePhase) * 0.2;
        this.ringMesh.scale.setScalar(pulseScale);
        this.coreMesh.scale.setScalar(1 + (pulseScale - 1) * 0.5);

        // Check if out of bounds
        if (this.position.y < -12) {
            this.active = false;
        }
    }

    dispose() {
        this.ringMesh.geometry.dispose();
        this.ringMesh.material.dispose();
        this.coreMesh.geometry.dispose();
        this.coreMesh.material.dispose();

        if (this.mesh.parent) {
            this.mesh.parent.remove(this.mesh);
        }
        this.mesh.clear();
    }

    getType() {
        return this.type;
    }

    getPosition() {
        return this.position;
    }
}

import { InstancedMeshManager } from '../../shared/rendering/InstancedMeshManager.js';
import { GeometryPool } from '../../shared/rendering/GeometryPool.js';
import { PBRMaterialFactory } from '../../shared/rendering/PBRMaterialFactory.js';
import { TextureGenerator } from '../assets/TextureGenerator.js';

export class InvaderGrid {
    constructor(scene, x = 0, y = 4) {
        this.scene = scene;
        this.x = x;
        this.y = y;

        // Grid configuration
        this.rows = 5;
        this.cols = 10;
        this.totalInvaders = this.rows * this.cols;

        // Movement state
        this.direction = 1; // 1 = right, -1 = left
        this.moveSpeed = 2.0; // Base speed in units/second
        this.dropDistance = 1.5;
        this.moveTimer = 0;
        this.stepSize = 0.8; // How far to move each step

        // Invader data storage
        this.invaders = [];

        // Shooting state
        this.shootCooldown = 0;
        this.minShootInterval = 1.5; // Minimum seconds between shots

        // Animation state
        this.animationTimer = 0;
        this.animationFrame = 0;

        // Initialize invader data
        this.initInvaders();
    }

    initInvaders() {
        const spacingX = 2.5;
        const spacingY = 1.8;
        const startX = -((this.cols - 1) * spacingX) / 2;

        for (let row = 0; row < this.rows; row++) {
            for (let col = 0; col < this.cols; col++) {
                // Determine invader type based on row
                let type, points, color;
                if (row <= 1) {
                    type = 'squid';
                    points = 30;
                    color = 0xFF6B9D;
                } else if (row <= 3) {
                    type = 'crab';
                    points = 20;
                    color = 0x4ECDC4;
                } else {
                    type = 'octopus';
                    points = 10;
                    color = 0xFFE66D;
                }

                this.invaders.push({
                    row: row,
                    col: col,
                    type: type,
                    points: points,
                    color: color,
                    x: startX + col * spacingX,
                    y: this.y - row * spacingY,
                    alive: true,
                    animationOffset: Math.random() * Math.PI * 2
                });
            }
        }
    }

    update(delta, player) {
        // Update movement timer
        this.moveTimer += delta;

        // Calculate current speed based on remaining invaders
        const aliveCount = this.getAliveCount();
        if (aliveCount === 0) return false;

        const speedMultiplier = 1 + (1 - aliveCount / this.totalInvaders);
        const moveInterval = Math.max(0.05, 0.2 / speedMultiplier);

        // Move invaders in steps
        if (this.moveTimer >= moveInterval) {
            this.moveTimer = 0;

            // Check edge collision before moving
            let shouldReverse = false;
            const margin = 10;

            for (const invader of this.invaders) {
                if (!invader.alive) continue;

                if (this.direction === 1 && invader.x + margin > 12) {
                    shouldReverse = true;
                    break;
                } else if (this.direction === -1 && invader.x - margin < -12) {
                    shouldReverse = true;
                    break;
                }
            }

            if (shouldReverse) {
                this.direction *= -1;
                // Drop all invaders down
                for (const invader of this.invaders) {
                    if (invader.alive) {
                        invader.y -= this.dropDistance;
                    }
                }

                // Check if invaders reached player level
                const lowestY = Math.min(...this.invaders.filter(i => i.alive).map(i => i.y));
                if (lowestY <= -6) {
                    return 'gameover'; // Invaders reached bottom
                }
            } else {
                // Move all invaders horizontally
                for (const invader of this.invaders) {
                    if (invader.alive) {
                        invader.x += this.stepSize * this.direction;
                    }
                }
            }
        }

        // Update animation timer
        this.animationTimer += delta;
        if (this.animationTimer >= 0.3) {
            this.animationTimer = 0;
            this.animationFrame = (this.animationFrame + 1) % 2;
        }

        // Handle shooting
        this.shootCooldown -= delta;
        if (this.shootCooldown <= 0 && Math.random() < 0.3) {
            const shooter = this.getRandomShooter();
            if (shooter) {
                return { shot: true, x: shooter.x, y: shooter.y };
            }
        }

        return true; // Still active
    }

    getRandomShooter() {
        // Get all alive invaders grouped by column
        const columns = {};
        for (const invader of this.invaders) {
            if (!invader.alive) continue;

            if (!columns[invader.col]) {
                columns[invader.col] = [];
            }
            columns[invader.col].push(invader);
        }

        // Pick a random column with alive invaders
        const colKeys = Object.keys(columns).map(Number);
        if (colKeys.length === 0) return null;

        const selectedCol = colKeys[Math.floor(Math.random() * colKeys.length)];
        const columnInvaders = columns[selectedCol];

        // Pick the lowest invader in that column
        return columnInvaders.reduce((lowest, current) => 
            current.y < lowest.y ? current : lowest
        );
    }

    killInvader(index) {
        if (index >= 0 && index < this.invaders.length) {
            const invader = this.invaders[index];
            if (invader.alive) {
                invader.alive = false;
                return {
                    points: invader.points,
                    x: invader.x,
                    y: invader.y,
                    type: invader.type
                };
            }
        }
        return null;
    }

    getAliveCount() {
        return this.invaders.filter(i => i.alive).length;
    }

    isCleared() {
        return this.getAliveCount() === 0;
    }

    reset(scene, levelMultiplier = 1) {
        this.scene = scene;
        this.direction = 1;
        this.moveTimer = 0;
        this.animationFrame = 0;
        this.shootCooldown = Math.random();

        // Increase speed with each level
        this.moveSpeed = 2.0 * (1 + (levelMultiplier - 1) * 0.15);

        // Reinitialize invaders
        this.initInvaders();
    }

    // Get invader positions for rendering (used by InstancedMeshManager)
    getPositions() {
        return this.invaders.map(inv => ({
            x: inv.x,
            y: inv.y,
            type: inv.type,
            alive: inv.alive,
            animationFrame: this.animationFrame,
            animationOffset: inv.animationOffset
        }));
    }

    // Get bounding box for collision detection
    getBounds() {
        const aliveInvaders = this.invaders.filter(i => i.alive);
        if (aliveInvaders.length === 0) return null;

        const minX = Math.min(...aliveInvaders.map(i => i.x));
        const maxX = Math.max(...aliveInvaders.map(i => i.x));
        const minY = Math.min(...aliveInvaders.map(i => i.y));
        const maxY = Math.max(...aliveInvaders.map(i => i.y));

        return { minX, maxX, minY, maxY };
    }

    // Check if bullet hit any invader
    checkBulletHit(bulletX, bulletY) {
        for (let i = 0; i < this.invaders.length; i++) {
            const invader = this.invaders[i];
            if (!invader.alive) continue;

            // Simple distance-based collision
            const dx = bulletX - invader.x;
            const dy = bulletY - invader.y;
            const distance = Math.sqrt(dx * dx + dy * dy);

            if (distance < 1.0) {
                return { hit: true, index: i };
            }
        }

        return { hit: false, index: -1 };
    }

    dispose() {
        // Cleanup any resources held by this grid
        this.invaders = [];
    }
}

/**
 * GeometryPool - Reusable geometry cache for common shapes
 * Prevents redundant geometry creation and enables efficient disposal
 */

import * as THREE from 'three';

export class GeometryPool {
    constructor() {
        this.cache = new Map(); // key -> { geometry, refCount }

        // Pre-create commonly used geometries
        this._prewarmGeometries();
    }

    /**
     * Get a geometry by key, incrementing reference count
     * @param {string} key - Unique identifier for the geometry type
     * @param {Object} options - Optional override parameters
     * @returns {THREE.BufferGeometry} The cached or newly created geometry
     */
    get(key, options = {}) {
        const cacheEntry = this.cache.get(key);

        if (cacheEntry) {
            cacheEntry.refCount++;
            return cacheEntry.geometry;
        }

        // Create new geometry based on key pattern
        let geometry = this._createGeometryFromKey(key, options);

        if (!geometry) {
            console.warn(`GeometryPool: Unknown geometry key "${key}"`);
            // Fallback to box
            geometry = new THREE.BoxGeometry(1, 1, 1);
        }

        this.cache.set(key, { geometry, refCount: 1 });
        return geometry;
    }

    /**
     * Release a geometry, decrementing reference count
     * Disposes when refCount reaches zero
     * @param {string} key - The geometry key to release
     */
    release(key) {
        const cacheEntry = this.cache.get(key);

        if (!cacheEntry) return;

        cacheEntry.refCount--;

        if (cacheEntry.refCount <= 0) {
            // Dispose the geometry
            cacheEntry.geometry.dispose();
            this.cache.delete(key);
        }
    }

    /**
     * Manually add a custom geometry to the pool
     * @param {string} key - Unique identifier
     * @param {THREE.BufferGeometry} geometry - The geometry to store
     */
    add(key, geometry) {
        if (this.cache.has(key)) {
            console.warn(`GeometryPool: Key "${key}" already exists`);
            return;
        }

        this.cache.set(key, { geometry, refCount: 1 });
    }

    /**
     * Remove a geometry immediately without waiting for refCount
     * @param {string} key - The geometry key to remove
     */
    remove(key) {
        const cacheEntry = this.cache.get(key);

        if (!cacheEntry) return;

        cacheEntry.geometry.dispose();
        this.cache.delete(key);
    }

    /**
     * Clear all geometries from the pool
     * Use with caution - should only be called on full game reset
     */
    clear() {
        for (const [key, entry] of this.cache) {
            entry.geometry.dispose();
        }
        this.cache.clear();

        // Re-prewarm for next use
        this._prewarmGeometries();
    }

    /**
     * Get the current cache statistics
     * @returns {Object} Statistics about cached geometries
     */
    getStats() {
        let totalGeometries = 0;
        let totalRefCount = 0;

        for (const entry of this.cache.values()) {
            totalGeometries++;
            totalRefCount += entry.refCount;
        }

        return {
            cachedKeys: this.cache.size,
            totalGeometries,
            totalRefCount
        };
    }

    /**
     * Pre-warm commonly used geometries for instant access
     */
    _prewarmGeometries() {
        // Basic shapes
        this.get('box-1');           // Unit cube
        this.get('sphere-1');        // Unit sphere
        this.get('plane-1');         // Unit plane

        // Particle shapes
        this.get('particle-sphere');  // Small sphere for particles
        this.get('particle-cube');    // Cube variant for particles

        // UI elements
        this.get('ring-thin');       // Thin ring for shockwaves
        this.get('ring-medium');     // Medium ring

        // Game-specific shapes (will be extended per game)
        this.get('bullet-sphere');   // Bullet projectile shape
        this.get('bomb-cylinder');   // Bomb/missile shape

        // Release the prewarmed references (they stay in cache due to internal handling)
        // Actually, we want them cached, so we don't release - they have refCount 1
    }

    /**
     * Create geometry based on key pattern
     * @param {string} key - The geometry identifier
     * @param {Object} options - Override parameters
     * @returns {THREE.BufferGeometry|null} Created geometry or null if unknown
     */
    _createGeometryFromKey(key, options = {}) {
        const parts = key.split('-');
        const type = parts[0];

        switch (type) {
            case 'box':
                const width = parseFloat(parts[1]) || 1;
                const height = parseFloat(parts[2]) || 1;
                const depth = parseFloat(parts[3]) || 1;
                return new THREE.BoxGeometry(width, height, depth);

            case 'sphere':
                const radius = parseFloat(parts[1]) || 0.5;
                const widthSegs = parseInt(parts[2]) || 16;
                const heightSegs = parseInt(parts[3]) || 16;
                return new THREE.SphereGeometry(radius, widthSegs, heightSegs);

            case 'plane':
                const planeWidth = parseFloat(parts[1]) || 1;
                const planeHeight = parseFloat(parts[2]) || 1;
                return new THREE.PlaneGeometry(planeWidth, planeHeight);

            case 'cylinder':
                const cylRadiusTop = parseFloat(parts[1]) || 0.5;
                const cylRadiusBottom = parseFloat(parts[2]) || 0.5;
                const cylHeight = parseFloat(parts[3]) || 1;
                const cylRadSegs = parseInt(parts[4]) || 8;
                return new THREE.CylinderGeometry(cylRadiusTop, cylRadiusBottom, cylHeight, cylRadSegs);

            case 'cone':
                const coneRadius = parseFloat(parts[1]) || 0.5;
                const coneHeight = parseFloat(parts[2]) || 1;
                const coneRadSegs = parseInt(parts[3]) || 8;
                return new THREE.ConeGeometry(coneRadius, coneHeight, coneRadSegs);

            case 'torus':
                const torusRadius = parseFloat(parts[1]) || 0.5;
                const torusTube = parseFloat(parts[2]) || 0.1;
                const torusRadSegs = parseInt(parts[3]) || 8;
                const torusTubSegs = parseInt(parts[4]) || 16;
                return new THREE.TorusGeometry(torusRadius, torusTube, torusRadSegs, torusTubSegs);

            case 'particle':
                // Small optimized geometry for particles
                if (parts[1] === 'sphere') {
                    return new THREE.SphereGeometry(0.15, 6, 6);
                } else if (parts[1] === 'cube') {
                    return new THREE.BoxGeometry(0.2, 0.2, 0.2);
                }
                return new THREE.SphereGeometry(0.15, 6, 6);

            case 'ring':
                // Ring/torus for shockwaves and effects
                const ringThickness = parts[1] === 'thin' ? 0.08 : 
                                     parts[1] === 'thick' ? 0.2 : 0.1;
                return new THREE.TorusGeometry(0.5, ringThickness, 8, 24);

            case 'bullet':
                // Bullet/projectile shape
                if (parts[1] === 'sphere') {
                    return new THREE.SphereGeometry(0.15, 8, 8);
                } else if (parts[1] === 'cylinder') {
                    return new THREE.CylinderGeometry(0.08, 0.08, 0.6, 8);
                }
                return new THREE.SphereGeometry(0.15, 8, 8);

            case 'bomb':
                // Bomb/missile shape
                if (parts[1] === 'cylinder') {
                    return new THREE.CylinderGeometry(0.2, 0.15, 0.8, 8);
                } else if (parts[1] === 'sphere') {
                    return new THREE.SphereGeometry(0.3, 12, 12);
                }
                return new THREE.CylinderGeometry(0.2, 0.15, 0.8, 8);

            case 'invader':
                // Invader ship base shape (will be customized per type)
                if (parts[1] === 'squid') {
                    return this._createSquidGeometry();
                } else if (parts[1] === 'crab') {
                    return this._createCrabGeometry();
                } else if (parts[1] === 'octopus') {
                    return this._createOctopusGeometry();
                }
                return this._createDefaultInvaderGeometry();

            case 'player':
                // Player ship shape
                return this._createPlayerShipGeometry();

            case 'ufo':
                // UFO bonus ship
                return this._createUFOGeometry();

            case 'powerup':
                // Power-up collectible
                if (parts[1] === 'spread') {
                    return new THREE.OctahedronGeometry(0.3);
                } else if (parts[1] === 'shield') {
                    return new THREE.IcosahedronGeometry(0.3, 0);
                } else if (parts[1] === 'rapid') {
                    return new THREE.TetrahedronGeometry(0.3);
                } else if (parts[1] === 'health') {
                    return new THREE.SphereGeometry(0.25, 8, 8);
                }
                return new THREE.OctahedronGeometry(0.3);

            default:
                console.warn(`GeometryPool._createGeometryFromKey: Unknown type "${type}"`);
                return null;
        }
    }

    /**
     * Create player ship geometry (triangle fuselage)
     */
    _createPlayerShipGeometry() {
        const geometry = new THREE.BufferGeometry();

        // Triangle-based ship shape
        const vertices = new Float32Array([
            // Top point
            0, 0.8, 0,
            // Bottom left
            -0.6, -0.4, 0,
            // Bottom right
            0.6, -0.4, 0,
            // Center (for engine detail)
            0, -0.2, 0.15,
        ]);

        const indices = [
            0, 1, 2,  // Main triangle
            0, 3, 1,  // Left side with depth
            0, 2, 3,  // Right side with depth
            1, 3, 2   // Bottom with depth
        ];

        geometry.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
        geometry.setIndex(indices);
        geometry.computeVertexNormals();

        return geometry;
    }

    /**
     * Create squid invader geometry (top row)
     */
    _createSquidGeometry() {
        const geometry = new THREE.BoxGeometry(1.2, 0.8, 0.6);

        // Add some detail by creating a more complex shape
        const positions = geometry.attributes.position;
        const count = positions.count;

        // Modify vertices to create squid-like shape
        for (let i = 0; i < count; i++) {
            const y = positions.getY(i);
            if (y > 0) {
                // Narrow the top
                positions.setX(i, positions.getX(i) * 0.7);
                positions.setZ(i, positions.getZ(i) * 0.8);
            }
        }

        geometry.attributes.position.needsUpdate = true;
        geometry.computeVertexNormals();

        return geometry;
    }

    /**
     * Create crab invader geometry (middle rows)
     */
    _createCrabGeometry() {
        const geometry = new THREE.BoxGeometry(1.4, 0.9, 0.7);

        // Crab has wider body with "claws" on sides
        const positions = geometry.attributes.position;
        const count = positions.count;

        for (let i = 0; i < count; i++) {
            const x = positions.getX(i);
            const y = positions.getY(i);

            // Extend sides at mid-height for claws
            if (Math.abs(y) < 0.3 && Math.abs(x) > 0.5) {
                positions.setX(i, x * 1.2);
            }
        }

        geometry.attributes.position.needsUpdate = true;
        geometry.computeVertexNormals();

        return geometry;
    }

    /**
