/**
 * MotionTrailManager - Manages multiple motion trails efficiently
 */
export class MotionTrailManager {
    constructor() {
        this.trails = new Map(); // object.uuid -> MotionTrail
        this.maxTrails = 50;
    }

    create(object, options = {}) {
        if (this.trails.size >= this.maxTrails) {
            // Remove oldest trail
            const firstKey = this.trails.keys().next().value;
            this.remove(firstKey);
        }

        const trail = new MotionTrail(object, options);
        this.trails.set(object.uuid, trail);
        return trail;
    }

    get(object) {
        return this.trails.get(object.uuid);
    }

    updateAll(delta) {
        for (const trail of this.trails.values()) {
            trail.update(delta);
        }
    }

    remove(objectUuid) {
        const trail = this.trails.get(objectUuid);
        if (trail) {
            trail.dispose();
            this.trails.delete(objectUuid);
        }
    }

    clear() {
        for (const trail of this.trails.values()) {
            trail.dispose();
        }
        this.trails.clear();
    }

    dispose() {
        this.clear();
    }
}

